import {makeCircuit} from '../wiring-generator/model.mjs';
import {drawCircuit} from '../wiring-generator/render.mjs';
import {readGeneratorURL,generatorURL} from '../wiring-generator/session.mjs';
import {circuitForKit} from '../les-paul-kits/diagram.mjs';
import {specification} from '../les-paul-kits/config.mjs';
let saved;try{saved=readGeneratorURL(location.search);}catch(error){const root=document.querySelector('#guide-configuration');if(root)root.textContent=error.message;}
if(saved){document.querySelectorAll('[data-open-diagram]').forEach(a=>a.href=generatorURL(saved.state,saved.kit));const root=document.querySelector('#guide-configuration');if(root&&(saved.kit||location.search)){root.replaceChildren();const p=document.createElement('p');p.textContent=saved.kit?specification(saved.kit):`Saved circuit: ${saved.state.guitar}, ${saved.state.wiring}, ${saved.state.neckCap}µF neck / ${saved.state.bridgeCap}µF bridge, treble bleed: ${saved.state.bleed}.`;p.style.whiteSpace='pre-line';root.append(p);}}
for(const mount of document.querySelectorAll('[data-illustration]')){const mode=mount.dataset.illustration,c=mode==='installation'&&saved?.kit?circuitForKit(saved.kit,saved.state):makeCircuit(mode==='installation'&&saved?saved.state:{wiring:'modern',bleed:mode==='tone'?'duncan':'none'});let view='0 0 1320 1275',caption='Generated with the same Apparition Wiring Engine used by the Kit Builder.';if(mode==='pot'){c.components=c.components.filter(p=>p.id==='neckVolume');c.connections=[];c.contacts=[];view='345 225 190 225';caption='Rear view, lugs down. Left to right: Lug 3 (CW end), Lug 2 (wiper), Lug 1 (CCW end). Casing ground is separate.';}if(mode==='tone'){const ids=['neckVolume','neckTone','neckCap','neckBleedCap','neckBleedResistor'];c.components=c.components.filter(p=>ids.includes(p.id));c.connections=c.connections.filter(w=>ids.includes(w.from.split('.')[0])&&ids.includes(w.to.split('.')[0]));c.contacts=[];view='325 95 630 390';caption='Tone capacitor to the right; parallel treble bleed above the volume. Both are generated from terminal connections.';}mount.innerHTML=drawCircuit(c,{exporting:true});const svg=mount.querySelector('svg');svg.setAttribute('viewBox',view);svg.removeAttribute('id');svg.setAttribute('aria-label',caption);svg.removeAttribute('aria-labelledby');svg.querySelectorAll('[id]').forEach(n=>n.removeAttribute('id'));const note=document.createElement('figcaption');note.textContent=caption;mount.append(note);}
